mapper.select:
SELECT t.* FROM ds_design_token t
WHERE t.deleted = 0

    AND (t.token_name LIKE CONCAT('%', #{keyword}, '%')
    OR t.display_name LIKE CONCAT('%', #{keyword}, '%')
    OR t.description LIKE CONCAT('%', #{keyword}, '%'))


    AND t.token_type = #{tokenType}


    AND t.token_level = #{tokenLevel}


    AND t.category = #{category}

ORDER BY t.token_level, t.category, t.token_name

SELECT t.* FROM ds_design_token t
WHERE t.deleted = 0 AND t.inherits_from = #{inheritsFrom}
ORDER BY t.token_name

SELECT t.* FROM ds_design_token t
WHERE t.deleted = 0 AND t.token_level = #{tokenLevel}
ORDER BY t.category, t.token_name

SELECT t.* FROM ds_design_token t
WHERE t.deleted = 0 AND t.token_type = #{tokenType}
ORDER BY t.token_level, t.token_name

SELECT t.* FROM ds_design_token t
WHERE t.deleted = 0 AND t.token_name = #{tokenName}
LIMIT 1
